"""Validated outgoing HH text generated by humanizer-framework."""

from __future__ import annotations

import os
from pathlib import Path

from humanizer_framework import CommunicationFramework
from humanizer_framework.models import CommunicationResult

from .adapter import build_application_request, build_chat_reply_request


class FrameworkWriter:
    def __init__(self, framework: CommunicationFramework | None = None) -> None:
        os.environ.setdefault(
            "HUMANIZER_ENV_FILE", str(Path(__file__).resolve().parents[3] / ".env")
        )
        self._framework = framework or CommunicationFramework()

    def application(
        self, *, vacancy_name: str, employer_name: str, source_context: str
    ) -> CommunicationResult:
        return self._framework.generate(
            build_application_request(
                vacancy_name=vacancy_name,
                employer_name=employer_name,
                source_context=source_context,
            )
        )

    def chat_reply(
        self, *, context: list[str], initiated_by_us: bool,
        vacancy_name: str, employer_name: str, latest_message_text: str,
        resume_context: str = "",
    ) -> CommunicationResult:
        return self._framework.generate(
            build_chat_reply_request(
                context=context,
                initiated_by_us=initiated_by_us,
                vacancy_name=vacancy_name,
                employer_name=employer_name,
                latest_message_text=latest_message_text,
                resume_context=resume_context,
            )
        )
